1	import { assert, describe, it } from "@effect/vitest";
2	import {
3	  calculateRoundResult,
4	  enforceEffectiveNOnResult,
5	  type HistoricalRoundData,
6	  PulseId,
7	  type QuestionInput,
8	  QuestionVersionId,
9	  RoundId,
10	  type RoundResult,
11	  roundDecimals,
12	  type SubmissionAnswer,
13	  TeamId,
14	} from "@surveybeat/domain";
15	import * as Arbitrary from "effect/Arbitrary";
16	import * as Effect from "effect/Effect";
17	import { HttpApi } from "effect/http-api";
18	import * as Schema from "effect/Schema";
19	import { SurveyBeatApi } from "./index.ts";
20	import { privacyRegistry, RoundResultScenario } from "./PrivacyRegistry.ts";
21	
22	/** Every endpoint of the runtime declaration, as `group.endpoint`. */
23	const declaredEndpoints = (): ReadonlyArray<string> => {
24	  const keys: Array<string> = [];
25	  HttpApi.reflect(SurveyBeatApi, {
26	    onGroup: () => {},
27	    onEndpoint: ({ group, endpoint }) => keys.push(`${group.identifier}.${endpoint.identifier}`),
28	  });
29	  return keys;
30	};
31	
32	describe("privacy registry", () => {
33	  it("classifies every endpoint of SurveyBeatApi", () => {
34	    const unlisted = declaredEndpoints().filter((key) => !Object.hasOwn(privacyRegistry, key));
35	    assert.deepStrictEqual(unlisted, [], "add these endpoints to privacyRegistry in PrivacyRegistry.ts");
36	  });
37	
38	  it("lists no endpoint that the declaration does not have", () => {
39	    const declared = new Set(declaredEndpoints());
40	    const stale = Object.keys(privacyRegistry).filter((key) => !declared.has(key));
41	    assert.deepStrictEqual(stale, []);
42	  });
43	
44	  it("enumerates the declaration, so the checks above are not vacuous", () => {
45	    assert.include(declaredEndpoints(), "auth.session");
46	  });
47	
48	  it("has an input generator for every Result-bearing endpoint, and a check that consumes it", () => {
49	    const resultEndpoints = Object.entries(privacyRegistry)
50	      .filter(([, entry]) => entry._tag === "ResultData")
51	      .map(([key]) => key)
52	      .sort();
53	    assert.deepStrictEqual(resultEndpoints, Object.keys(resultResponders).sort());
54	    assert.include(resultEndpoints, "rounds.getResults");
55	  });
56	
57	  for (const [key, entry] of Object.entries(privacyRegistry)) {
58	    if (entry._tag !== "ResultData") continue;
59	    const respond = resultResponders[key];
60	
61	    // Property test over the registry's own generator: whatever Round the generator produces, the
62	    // endpoint's Result shows no aggregate computed from fewer than the effective N contributors.
63	    it.effect(`${key}: no aggregate below the effective N for any generated Round (ADR 0004)`, () =>
64	      Effect.gen(function* () {
65	        assert.isDefined(respond, `no Result check registered for ${key}`);
66	        const check = yield* Arbitrary.checkEffect(
67	          entry.inputs,
68	          (input) =>
69	            Effect.suspend(() => {
70	              const scenario = Schema.decodeUnknownSync(RoundResultScenario)(input);
71	              const failures = violations(scenario, respond(scenario));
72	              return failures.length > 0 ? Effect.fail(failures.join("; ")) : Effect.succeed(true);
73	            }),
74	          { runs: 500, seed: 20261109 },
75	        );
76	        assert.strictEqual(Arbitrary.formatCheckFailure(check), undefined);
77	        assert.strictEqual(check._tag, "Passed");
78	      }),
79	    );
80	  }
81	});
82	
83	// --- The Result-shaped response of each Result-bearing endpoint, built the way the handler builds it ---
84	
85	interface Built {
86	  readonly effectiveN: number;
87	  readonly questions: ReadonlyArray<QuestionInput>;
88	  readonly submissions: ReadonlyArray<{
89	    readonly id: string;
90	    readonly answers: ReadonlyArray<SubmissionAnswer>;
91	  }>;
92	  readonly result: RoundResult;
93	  /** The same Round computed from scratch at the effective N: the most that may ever be shown. */
94	  readonly direct: RoundResult;
95	}
96	
97	const DIMENSIONS = ["workload", "psychologicalSafety", "clarity", "recognition"] as const;
98	const ROUND = RoundId.make("round-now");
99	const PULSE = PulseId.make("pulse-1");
100	const TEAM = TeamId.make("team-1");
101	const OPTIONS = ["Red", "Green", "Blue"];
102	
103	const buildResult = (scenario: RoundResultScenario): Built => {
104	  const effectiveN = Math.max(scenario.storedN, scenario.organizationN);
105	  const questions: ReadonlyArray<QuestionInput> = scenario.questions.map((question, index) => ({
106	    id: QuestionVersionId.make(`q${index}.1`),
107	    position: index,
108	    text: `Question ${index}`,
109	    dimension: question.dimension,
110	    type:
111	      question.kind === "rating"
112	        ? { _tag: "Rating", lowLabel: "Low", highLabel: "High", comment: true }
113	        : question.kind === "choice"
114	          ? { _tag: "SingleChoice", options: OPTIONS }
115	          : { _tag: "LongText" },
116	  }));
117	  const submissions = scenario.submissions.map((submission, s) => ({
118	    id: `s${s}`,
119	    answers: questions.flatMap((question, index): ReadonlyArray<SubmissionAnswer> => {
120	      const answer = submission[index];
121	      if (answer === undefined || !answer.answered) return [];
122	      const kind = scenario.questions[index]?.kind;
123	      return [
124	        {
125	          questionVersionId: question.id,
126	          value:
127	            kind === "rating" ? answer.value + 1 : kind === "choice" ? answer.value % OPTIONS.length : null,
128	          comment: kind === "choice" ? null : answer.comment,
129	        },
130	      ];
131	    }),
132	  }));
133	  const history: ReadonlyArray<HistoricalRoundData> = scenario.history.map((past, i) => {
134	    const usable = (score: number | null, contributors: number) =>
135	      score !== null &&
136	      contributors >= past.effectiveMinimumGroupSize &&
137	      past.submissionsCount >= contributors
138	        ? score
139	        : null;
140	    return {
141	      roundId: RoundId.make(`past-${i}`),
142	      plannedOpenDate: new Date(Date.UTC(2025, 0, 6 + 7 * i)).toISOString().slice(0, 10),
143	      closedAt: 1_700_000_000_000 + i,
144	      effectiveMinimumGroupSize: past.effectiveMinimumGroupSize,
145	      submissionsCount: past.submissionsCount,
146	      questions: questions.map((question, index) => {
147	        const slot = past.questions[index];
148	        const score = usable(slot?.score ?? null, slot?.contributors ?? 0);
149	        return {
150	          questionVersionId: question.id,
151	          score,
152	          contributors: slot?.contributors ?? 0,
153	          meetsMinimumGroupSize: score !== null,
154	        };
155	      }),
156	      dimensions: DIMENSIONS.map((dimension, index) => {
157	        const slot = past.dimensions[index];
158	        const score = usable(slot?.score ?? null, slot?.contributors ?? 0);
159	        return {
160	          dimension,
161	          score,
162	          usableQuestionCount: slot?.usableQuestionCount ?? 0,
163	          contributors: slot?.contributors ?? 0,
164	          meetsMinimumGroupSize: score !== null,
165	        };
166	      }),
167	    };
168	  });
169	  const compute = (effectiveMinimumGroupSize: number): RoundResult =>
170	    calculateRoundResult({
171	      roundId: ROUND,
172	      pulseId: PULSE,
173	      teamId: TEAM,
174	      status: scenario.status,
175	      plannedOpenDate: "2026-11-09",
176	      anonymityMode: "anonymous",
177	      closedAt: scenario.status === "open" ? null : 1_731_140_000_000,
178	      effectiveMinimumGroupSize,
179	      eligibleMembersCount: scenario.eligibleMembers,
180	      questions,
181	      submissions,
182	      pastRoundsHistory: history,
183	    });
184	  return {
185	    effectiveN,
186	    questions,
187	    submissions,
188	    // What `Organization.viewResults` returns: the Result stored under the Round's own N, then the
189	    // current Organization N applied on read (Rule R9).
190	    result: enforceEffectiveNOnResult(compute(scenario.storedN), scenario.organizationN),
191	    direct: compute(effectiveN),
192	  };
193	};
194	
195	const resultResponders: Record<string, (scenario: RoundResultScenario) => Built> = {
196	  "rounds.getResults": buildResult,
197	};
198	
199	/** Contributors to a Question counted from the raw Submissions, never from the Result under test. */
200	const contributorsOf = (built: Built, index: number): number => {
201	  const question = built.questions[index];
202	  if (question === undefined) return 0;
203	  return built.submissions.filter((submission) =>
204	    submission.answers.some(
205	      (answer) =>
206	        answer.questionVersionId === question.id &&
207	        (question.type._tag === "LongText"
208	          ? answer.comment !== null && answer.comment.trim().length > 0
209	          : answer.value !== null),
210	    ),
211	  ).length;
212	};
213	
214	/** Every way the Result shows an aggregate that fewer than the effective N contributors stand behind. */
215	const violations = (scenario: RoundResultScenario, built: Built): ReadonlyArray<string> => {
216	  const { result, direct, effectiveN: n } = built;
217	  const found: Array<string> = [];
218	  const open = scenario.status === "open";
219	  const roundMeetsN = !open && result.submissionsCount >= n;
220	  if (result.submissionsCount !== scenario.submissions.length) found.push("submissionsCount differs");
221	
222	  if (!roundMeetsN && result.comments.length > 0) found.push("comments shown below N");
223	  if (roundMeetsN) {
224	    const raw = built.submissions
225	      .flatMap((submission) => submission.answers)
226	      .filter((a) => a.comment?.trim());
227	    if (result.comments.length > raw.length) found.push("more comments than the Submissions carry");
228	  }
229	
230	  const visibleScore = new Map<string, number>();
231	  result.questions.forEach((question, index) => {
232	    const label = `question ${index}`;
233	    const expected = contributorsOf(built, index);
234	    const shown = question.score !== null || question.distribution !== null;
235	    if (shown && !(roundMeetsN && expected >= n)) {
236	      found.push(`${label} shows an aggregate from ${expected} contributors (N=${n})`);
237	    }
238	    if (!shown && (question.change !== null || question.typicalChange !== null)) {
239	      found.push(`${label} shows a change or typical change without a visible score`);
240	    }
241	    if (question.score !== null) visibleScore.set(question.questionVersionId, question.score);
242	    for (const point of question.trend) {
243	      if (point.score !== null && point.contributors < n) {
244	        found.push(
245	          `${label} trend point ${point.roundId} shows a score from ${point.contributors} contributors`,
246	        );
247	      }
248	      if (point.roundId === ROUND && point.score !== null && !shown) {
249	        found.push(`${label} current trend point shows a score the Question hides`);
250	      }
251	    }
252	    // Never more than a fresh computation at the effective N would show, and never different.
253	    const fresh = direct.questions[index];
254	    if (
255	      shown &&
256	      (question.score !== fresh?.score ||
257	        !Object.is(JSON.stringify(question.distribution), JSON.stringify(fresh?.distribution)))
258	    ) {
259	      found.push(`${label} differs from the Result computed at N=${n}`);
260	    }
261	    if (question.change !== null && JSON.stringify(question.change) !== JSON.stringify(fresh?.change)) {
262	      found.push(`${label} change differs from the Result computed at N=${n}`);
263	    }
264	    if (
265	      question.typicalChange !== null &&
266	      JSON.stringify(question.typicalChange) !== JSON.stringify(fresh?.typicalChange)
267	    ) {
268	      found.push(`${label} typical change differs from the Result computed at N=${n}`);
269	    }
270	    question.trend.forEach((point, p) => {
271	      const freshPoint = fresh?.trend[p];
272	      if (point.score !== null && point.score !== freshPoint?.score) {
273	        found.push(`${label} trend point ${point.roundId} differs from the Result computed at N=${n}`);
274	      }
275	    });
276	  });
277	
278	  result.dimensions.forEach((dimension) => {
279	    const label = `dimension ${dimension.dimension}`;
280	    const usable = built.questions
281	      .map((question, index) => ({ question, index }))
282	      .filter(
283	        ({ question, index }) =>
284	          question.type._tag === "Rating" &&
285	          question.dimension === dimension.dimension &&
286	          roundMeetsN &&
287	          contributorsOf(built, index) >= n,
288	      );
289	    if (dimension.score === null) {
290	      if (dimension.contributors !== undefined && dimension.contributors !== null) {
291	        found.push(`${label} shows contributors without a score`);
292	      }
293	      if (dimension.change !== null || dimension.typicalChange !== null) {
294	        found.push(`${label} shows a change or typical change without a score`);
295	      }
296	    } else {
297	      const ids = new Set(usable.map(({ question }) => question.id));
298	      const contributors = built.submissions.filter((submission) =>
299	        submission.answers.some((answer) => answer.value !== null && ids.has(answer.questionVersionId)),
300	      ).length;
301	      if (usable.length === 0 || contributors < n) {
302	        found.push(`${label} shows a score from ${contributors} contributors (N=${n})`);
303	      }
304	      const scores = usable.map(({ question }) => visibleScore.get(question.id));
305	      if (scores.some((score) => score === undefined)) {
306	        found.push(`${label} is computed from a Question that is hidden`);
307	      } else {
308	        const mean = roundDecimals(
309	          scores.reduce<number>((sum, score) => sum + (score ?? 0), 0) / scores.length,
310	          2,
311	        );
312	        if (mean !== dimension.score)
313	          found.push(`${label} score ${dimension.score} is not the mean of the visible Questions ${mean}`);
314	      }
315	      if (
316	        dimension.contributors !== undefined &&
317	        dimension.contributors !== null &&
318	        dimension.contributors < n
319	      ) {
320	        found.push(`${label} reports ${dimension.contributors} contributors (N=${n})`);
321	      }
322	    }
323	    for (const point of dimension.trend) {
324	      if (point.score !== null && (point.contributors === undefined || point.contributors < n)) {
325	        found.push(
326	          `${label} trend point ${point.roundId} shows a score from ${point.contributors ?? "unknown"} contributors`,
327	        );
328	      }
329	    }
330	    const fresh = direct.dimensions.find((each) => each.dimension === dimension.dimension);
331	    if (dimension.score !== null && dimension.score !== fresh?.score) {
332	      found.push(`${label} differs from the Result computed at N=${n}`);
333	    }
334	    if (
335	      dimension.typicalChange !== null &&
336	      JSON.stringify(dimension.typicalChange) !== JSON.stringify(fresh?.typicalChange)
337	    ) {
338	      found.push(`${label} typical change differs from the Result computed at N=${n}`);
339	    }
340	    if (dimension.change !== null && JSON.stringify(dimension.change) !== JSON.stringify(fresh?.change)) {
341	      found.push(`${label} change differs from the Result computed at N=${n}`);
342	    }
343	  });
344	  return found;
345	};
