1	import * as Data from "effect/Data";
2	import * as Effect from "effect/Effect";
3	import * as Option from "effect/Option";
4	import * as Schema from "effect/Schema";
5	import { AiClient, type AiInput, type AiRequest, RedactedText } from "../ai/AiClient.ts";
6	import { redact, type Roster } from "../privacy/Redaction.ts";
7	import { DiscussionGuide, enforceEffectiveNOnResult, type RoundResult } from "./Results.ts";
8	
9	/** What round_themes stores once (never recomputed). */
10	export const StoredThemes = Schema.Struct({
11	  themes: Schema.Array(
12	    Schema.Struct({ label: Schema.String, sentence: Schema.String, supportingComments: Schema.Int }),
13	  ),
14	  guide: Schema.NullOr(DiscussionGuide),
15	});
16	export type StoredThemes = typeof StoredThemes.Type;
17	
18	/** The object's record of the one themes call for a Round. */
19	export type RoundThemesRecord =
20	  | { readonly status: "pending"; readonly requestedAt: number; readonly attempts: number }
21	  | { readonly status: "ready"; readonly themes: StoredThemes }
22	  | { readonly status: "failed" };
23	
24	export const MAX_THEMES = 5;
25	export const MIN_SUPPORTING_COMMENTS = 2;
26	export const QUOTE_RUN_WORDS = 6;
27	export const THEMES_RETRY_WINDOW_MS = 24 * 3600_000;
28	
29	const FIRST_RETRY_GAP_MS = 5 * 60_000;
30	const MAX_RETRY_GAP_MS = 4 * 3600_000;
31	
32	/** ADR 0016/0019: only when AI processing is on and the Round meets N. */
33	export const shouldRequestThemes = (result: RoundResult, aiProcessing: boolean): boolean =>
34	  aiProcessing &&
35	  result.meetsMinimumGroupSize &&
36	  !result.delayed &&
37	  (result.status === "closed" || result.status === "ready" || result.status === "shared");
38	
39	/**
40	 * Builds the only thing sent to the model. Comments come from the stored Result (already redacted
41	 * at store time, ADR 0009), in the stored (shuffled) order: index i = result.comments[i].
42	 * Action titles are redacted here with `redact(title, roster)`.
43	 */
44	export const buildThemesInput = (
45	  result: RoundResult,
46	  openActionTitles: ReadonlyArray<string>,
47	  roster: Roster,
48	): AiInput => {
49	  const questionPositions = new Map(result.questions.map((q) => [q.questionVersionId, q.position]));
50	  return {
51	    questions: result.questions.map((q) => ({
52	      position: q.position,
53	      text: q.text,
54	      dimension: q.dimension,
55	      score: q.meetsMinimumGroupSize ? q.score : null,
56	      change: q.change?.change ?? null,
57	      largerThanUsual: q.change?.highlight?.isLargerThanUsual ?? false,
58	    })),
59	    dimensions: result.dimensions
60	      .filter((d) => d.meetsMinimumGroupSize)
61	      .map((d) => ({
62	        dimension: d.dimension,
63	        score: d.score,
64	        change: d.change?.change ?? null,
65	        largerThanUsual: d.change?.highlight?.isLargerThanUsual ?? false,
66	      })),
67	    comments: result.meetsMinimumGroupSize
68	      ? result.comments.map((c) => ({
69	          questionPosition: questionPositions.get(c.questionVersionId) ?? -1,
70	          text: RedactedText.make(c.text),
71	        }))
72	      : [],
73	    actions: openActionTitles.flatMap((title) => {
74	      const redacted = redact(title, roster);
75	      return redacted.trim() === "" ? [] : [{ title: RedactedText.make(redacted) }];
76	    }),
77	  };
78	};
79	
80	export const THEMES_SCHEMA_NAME = "comment_themes_and_guide";
81	
82	/**
83	 * Strict JSON schema sent as response_format (ADR 0015). Every object: type object, all properties
84	 * required, additionalProperties false. Limits are stated in descriptions and enforced in
85	 * `checkThemesReply`, because provider strict mode rejects maxItems, minimum and minLength.
86	 */
87	export const themesJsonSchema: Record<string, unknown> = {
88	  type: "object",
89	  additionalProperties: false,
90	  required: ["themes", "guide"],
91	  properties: {
92	    themes: {
93	      type: "array",
94	      description: `At most ${MAX_THEMES} Comment themes. Each needs at least ${MIN_SUPPORTING_COMMENTS} supporting comments.`,
95	      items: {
96	        type: "object",
97	        additionalProperties: false,
98	        required: ["label", "sentence", "supportingCommentIndexes"],
99	        properties: {
100	          label: { type: "string", description: "A short label of 6 words or fewer." },
101	          sentence: {
102	            type: "string",
103	            description: "One neutral sentence that paraphrases the theme. Never quote a comment.",
104	          },
105	          supportingCommentIndexes: {
106	            type: "array",
107	            description: "Indexes, counted from 0, of the comments that support this theme.",
108	            items: { type: "integer" },
109	          },
110	        },
111	      },
112	    },
113	    guide: {
114	      type: "object",
115	      additionalProperties: false,
116	      required: ["whatStoodOut", "whatPeopleRaised", "actionsToCheckOn", "questions"],
117	      properties: {
118	        whatStoodOut: {
119	          type: "array",
120	          description: "What stood out in the scores and changes, especially larger-than-usual changes.",
121	          items: { type: "string" },
122	        },
123	        whatPeopleRaised: {
124	          type: "array",
125	          description: "What people raised in the comments, paraphrased. Never quote.",
126	          items: { type: "string" },
127	        },
128	        actionsToCheckOn: {
129	          type: "array",
130	          description: "Only titles from the given open Actions. Empty when there are none.",
131	          items: { type: "string" },
132	        },
133	        questions: {
134	          type: "array",
135	          description: "At most 3 open questions the Lead can ask the Team.",
136	          items: { type: "string" },
137	        },
138	      },
139	    },
140	  },
141	};
142	
143	export const themesInstructions = [
144	  "You write the Comment themes and the discussion guide for one Round of a Team's pulse check.",
145	  "You receive the Round's anonymous data as JSON: questions with scores and changes, dimensions with scores and changes (largerThanUsual marks a change that is bigger than usual), comments indexed from 0, and the titles of open Actions.",
146	  `Write at most ${MAX_THEMES} Comment themes. Each has a short label of 6 words or fewer and one neutral sentence, plus the indexes of the comments that support it.`,
147	  `Only write a theme that at least ${MIN_SUPPORTING_COMMENTS} comments support.`,
148	  `Paraphrase. Never quote a comment and never reuse ${QUOTE_RUN_WORDS} or more consecutive words from a comment.`,
149	  "Never say or guess who wrote a comment, never name anyone, and never mention anything that is not in the input.",
150	  "Keep the wording neutral. Never advise punishing or praising an individual.",
151	  "The discussion guide has four lists:",
152	  "- whatStoodOut: what stood out in the scores and changes, especially the larger-than-usual ones.",
153	  "- whatPeopleRaised: what people raised in the comments, paraphrased.",
154	  "- actionsToCheckOn: only titles from the given open Actions; empty when there are none.",
155	  "- questions: at most 3 open questions the Lead can ask the Team.",
156	  "The same rules apply to the guide: paraphrase, never quote, and never say who said what.",
157	  "With no comments, return no themes and build the guide from the scores and Actions.",
158	  "Reply only with JSON that matches the schema.",
159	].join("\n");
160	
161	export const themesRequest = (input: AiInput): AiRequest => ({
162	  instructions: themesInstructions,
163	  input,
164	  schemaName: THEMES_SCHEMA_NAME,
165	  schema: themesJsonSchema,
166	  maxTokens: 2000,
167	});
168	
169	/**
170	 * Lowercased words of `text` with diacritics removed, split on anything that is not a letter or a
171	 * number. Word-based, so scripts written without spaces are not covered (SurveyBeat ships English and
172	 * German, ADR 0018).
173	 */
174	const wordsOf = (text: string): ReadonlyArray<string> =>
175	  text
176	    .normalize("NFKD")
177	    .replace(/\p{M}/gu, "")
178	    .toLowerCase()
179	    .split(/[^\p{L}\p{N}]+/u)
180	    .filter((word) => word.length > 0);
181	
182	/** Every window of QUOTE_RUN_WORDS consecutive words, joined by a space. */
183	const runsOf = (text: string): Set<string> => {
184	  const words = wordsOf(text);
185	  const runs = new Set<string>();
186	  for (let i = 0; i + QUOTE_RUN_WORDS <= words.length; i++) {
187	    runs.add(words.slice(i, i + QUOTE_RUN_WORDS).join(" "));
188	  }
189	  return runs;
190	};
191	
192	/** True when `text` repeats QUOTE_RUN_WORDS or more consecutive words of any comment (ADR 0016). */
193	export const repeatsCommentWords = (text: string, comments: ReadonlyArray<string>): boolean => {
194	  const commentRuns = new Set(comments.flatMap((comment) => [...runsOf(comment)]));
195	  return [...runsOf(text)].some((run) => commentRuns.has(run));
196	};
197	
198	export class ThemesReplyInvalid extends Data.TaggedError("ThemesReplyInvalid") {}
199	
200	const ReplyEnvelope = Schema.Struct({
201	  themes: Schema.Array(Schema.Unknown),
202	  guide: Schema.optionalKey(Schema.Unknown),
203	});
204	
205	const ThemeReply = Schema.Struct({
206	  label: Schema.String.pipe(Schema.check(Schema.isMinLength(1))),
207	  sentence: Schema.String.pipe(Schema.check(Schema.isMinLength(1))),
208	  supportingCommentIndexes: Schema.Array(Schema.Int),
209	});
210	
211	const decodeEnvelope = Schema.decodeUnknownOption(ReplyEnvelope);
212	const decodeThemeReply = Schema.decodeUnknownOption(ThemeReply);
213	const decodeGuide = Schema.decodeUnknownOption(DiscussionGuide);
214	
215	/**
216	 * ADR 0016/0019 checks on the model's reply. Fails only when the top level is not an object with a
217	 * `themes` array. Otherwise the reply is cleaned, never repaired:
218	 * - only the first MAX_THEMES entries are considered; an entry that does not decode is dropped;
219	 * - supportingComments counts distinct in-range comment indexes; fewer than 2 drops the theme;
220	 * - a label or sentence that repeats a 6-word run of any comment drops the theme;
221	 * - the guide must decode as DiscussionGuide, and no string in it may repeat a 6-word run; otherwise
222	 *   the whole guide is null.
223	 */
224	export const checkThemesReply = (
225	  reply: unknown,
226	  comments: ReadonlyArray<string>,
227	): Effect.Effect<StoredThemes, ThemesReplyInvalid> => {
228	  const envelope = Option.getOrNull(decodeEnvelope(reply));
229	  if (envelope === null) {
230	    return Effect.fail(new ThemesReplyInvalid());
231	  }
232	
233	  const themes = envelope.themes.slice(0, MAX_THEMES).flatMap((entry) => {
234	    const decoded = Option.getOrNull(decodeThemeReply(entry));
235	    if (decoded === null) return [];
236	    const supporters = new Set(
237	      decoded.supportingCommentIndexes.filter((index) => index >= 0 && index < comments.length),
238	    ).size;
239	    if (supporters < MIN_SUPPORTING_COMMENTS) return [];
240	    // Checked together too, so a quote split between the label and the sentence is caught.
241	    if (repeatsCommentWords(`${decoded.label} ${decoded.sentence}`, comments)) {
242	      return [];
243	    }
244	    return [{ label: decoded.label, sentence: decoded.sentence, supportingComments: supporters }];
245	  });
246	
247	  const guide = Option.getOrNull(decodeGuide(envelope.guide));
248	  const guideRepeats =
249	    guide === null ||
250	    [...guide.whatStoodOut, ...guide.whatPeopleRaised, ...guide.actionsToCheckOn, ...guide.questions].some(
251	      (text) => repeatsCommentWords(text, comments),
252	    );
253	
254	  return Effect.succeed({ themes, guide: guideRepeats ? null : guide });
255	};
