257	/**
258	 * Backoff for the k-th failed attempt (k >= 1): min(5 min * 2^(k-1), 4 h). Returns the next due
259	 * time, or null when it would fall after requestedAt + 24 h (give up).
260	 */
261	export const nextThemesAttemptAt = (
262	  requestedAt: number,
263	  failedAttempts: number,
264	  now: number,
265	): number | null => {
266	  const k = Math.max(1, failedAttempts);
267	  const gap = Math.min(FIRST_RETRY_GAP_MS * 2 ** (k - 1), MAX_RETRY_GAP_MS);
268	  const dueAt = now + gap;
269	  return dueAt > requestedAt + THEMES_RETRY_WINDOW_MS ? null : dueAt;
270	};
271	
272	export type ThemesJobDecision =
273	  | { readonly _tag: "Store"; readonly themes: StoredThemes }
274	  | { readonly _tag: "RetryAt"; readonly dueAt: number; readonly attempts: number }
275	  | { readonly _tag: "GiveUp" };
276	
277	/**
278	 * One attempt of the Round's single themes call. AiNotConfigured gives up, since nothing will change.
279	 * AiRejected, AiUnavailable and ThemesReplyInvalid retry at the backoff time, or give up once the
280	 * window is over. Never logs the reply or an error body.
281	 */
282	export const runThemesAttempt = (params: {
283	  readonly input: AiInput;
284	  readonly requestedAt: number;
285	  readonly attempts: number;
286	  readonly now: number;
287	}): Effect.Effect<ThemesJobDecision, never, AiClient> => {
288	  const comments = params.input.comments.map((c) => c.text);
289	  const retry = (): ThemesJobDecision => {
290	    const failedAttempts = params.attempts + 1;
291	    const dueAt = nextThemesAttemptAt(params.requestedAt, failedAttempts, params.now);
292	    return dueAt === null ? { _tag: "GiveUp" } : { _tag: "RetryAt", dueAt, attempts: failedAttempts };
293	  };
294	
295	  return AiClient.use((client) => client.complete(themesRequest(params.input))).pipe(
296	    Effect.flatMap((reply) => checkThemesReply(reply, comments)),
297	    Effect.map((themes): ThemesJobDecision => ({ _tag: "Store", themes })),
298	    Effect.catchTags({
299	      AiNotConfigured: (): Effect.Effect<ThemesJobDecision> => Effect.succeed({ _tag: "GiveUp" }),
300	      AiRejected: (): Effect.Effect<ThemesJobDecision> => Effect.succeed(retry()),
301	      AiUnavailable: (): Effect.Effect<ThemesJobDecision> => Effect.succeed(retry()),
302	      ThemesReplyInvalid: (): Effect.Effect<ThemesJobDecision> => Effect.succeed(retry()),
303	    }),
304	  );
305	};
