307	/**
308	 * The Result as one viewer may see it (ADR 0004, 0016, 0019). Single source of truth used by the
309	 * Organization object and the privacy tests.
310	 */
311	export const viewRoundResult = (params: {
312	  readonly stored: RoundResult;
313	  readonly organizationN: number;
314	  readonly isLead: boolean;
315	  readonly themes: RoundThemesRecord | null;
316	}): RoundResult => {
317	  // Theme fields come only from the themes record, never from whatever the stored Result carries.
318	  const {
319	    themes: _themes,
320	    themesStatus: _themesStatus,
321	    discussionGuide: _discussionGuide,
322	    ...r
323	  } = enforceEffectiveNOnResult(params.stored, params.organizationN);
324	  const shown: RoundResult = { ...r, comments: params.isLead ? r.comments : [] };
325	
326	  const hidden = (status: "notRequested" | "preparing" | "unavailable"): RoundResult => ({
327	    ...shown,
328	    themesStatus: status,
329	    themes: [],
330	    ...(params.isLead ? { discussionGuide: null } : {}),
331	  });
332	
333	  const record = params.themes;
334	  if (!r.meetsMinimumGroupSize || record === null) return hidden("notRequested");
335	
336	  switch (record.status) {
337	    case "pending":
338	      return hidden("preparing");
339	    case "failed":
340	      return hidden("unavailable");
341	    case "ready":
342	      if (!params.isLead) {
343	        return {
344	          ...shown,
345	          themesStatus: "ready",
346	          themes: record.themes.themes.map(({ label, sentence }) => ({ label, sentence })),
347	        };
348	      }
349	      return {
350	        ...shown,
351	        themesStatus: "ready",
352	        themes: record.themes.themes,
353	        discussionGuide: record.themes.guide,
354	      };
355	  }
356	};
