257	/**
258	 * Backoff for the k-th failed attempt (k >= 1): min(5 min * 2^(k-1), 4 h). Returns the next due
259	 * time, or null when it would fall after requestedAt + 24 h (give up).
260	 */
261	export const nextThemesAttemptAt = (
262	  requestedAt: number,
263	  failedAttempts: number,
264	  now: number,
265	): number | null => {
266	  const k = Math.max(1, failedAttempts);
267	  const gap = Math.min(FIRST_RETRY_GAP_MS * 2 ** (k - 1), MAX_RETRY_GAP_MS);
268	  const dueAt = now + gap;
269	  return dueAt > requestedAt + THEMES_RETRY_WINDOW_MS ? null : dueAt;
270	};
